-- Robust invitation provisioning: link invited users to the existing workspace without relying on user metadata.\n\ncreate table if not exists public.image_manager_invitations (\n  id uuid primary key default gen_random_uuid(),\n  tenant_id uuid not null references public.tenants(id) on delete cascade,\n  email text not null,\n  role text not null default 'member' check (role in ('admin','member','viewer')),\n  invited_user_id uuid references auth.users(id) on delete set null,\n  expires_at timestamptz not null default (now() + interval '7 days'),\n  accepted_at timestamptz,\n  created_at timestamptz not null default now()\n);\n\ncreate index if not exists image_manager_invitations_email_idx on public.image_manager_invitations(lower(email));\ncreate index if not exists image_manager_invitations_tenant_idx on public.image_manager_invitations(tenant_id);\nalter table public.image_manager_invitations enable row level security;\n\ncreate or replace function public.handle_new_image_manager_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  new_tenant_id uuid;\n  display_name text;\n  base_slug text;\n  invitation record;\nbegin\n  select * into invitation\n  from public.image_manager_invitations\n  where lower(email) = lower(new.email)\n    and accepted_at is null\n    and expires_at > now()\n  order by created_at desc\n  limit 1;\n\n  if invitation.id is not null then\n    insert into public.memberships (tenant_id, user_id, role)\n    values (invitation.tenant_id, new.id, invitation.role)\n    on conflict (tenant_id, user_id) do update set role = excluded.role;\n\n    update public.image_manager_invitations\n    set invited_user_id = new.id, accepted_at = now()\n    where id = invitation.id;\n\n    insert into public.audit_logs (tenant_id, user_id, action, entity_type, metadata)\n    values (invitation.tenant_id, new.id, 'member.invited', 'membership', jsonb_build_object('source','invitation','role',invitation.role));\n\n    return new;\n  end if;\n\n  display_name := coalesce(nullif(trim(new.raw_user_meta_data ->> 'company_name'), ''), split_part(new.email, '@', 1), 'Neuer Kunde');\n  base_slug := lower(regexp_replace(display_name, '[^a-zA-Z0-9]+', '-', 'g'));\n  base_slug := trim(both '-' from base_slug);\n  if base_slug = '' then base_slug := 'kunde'; end if;\n\n  insert into public.tenants (name, slug, plan, status)\n  values (display_name, base_slug || '-' || substr(replace(new.id::text, '-', ''), 1, 8), 'starter', 'trial')\n  returning id into new_tenant_id;\n\n  insert into public.memberships (tenant_id, user_id, role)\n  values (new_tenant_id, new.id, 'owner');\n\n  insert into public.audit_logs (tenant_id, user_id, action, entity_type, metadata)\n  values (new_tenant_id, new.id, 'tenant.created', 'tenant', jsonb_build_object('source', 'signup'));\n\n  return new;\nend;\n$$;\n